<script setup>
import { computed, ref, watch } from 'vue';
import Icon from '../../ui/EditionIcon.vue';
import Modal from '../../ui/EditionModal.vue';

const props=defineProps({loyalty:{type:Object,default:null},events:{type:Array,default:()=>[]},customers:{type:Array,default:()=>[]},currency:{type:String,default:'RM'},canConfigure:Boolean,canAdjust:Boolean,busy:Boolean,error:{type:String,default:''}});
const emit=defineEmits(['save-settings','post-event','reverse','refresh-events']);
const localError=ref(''),action=ref(null),reversal=ref(null),settings=ref({});
const sourceSettings=computed(()=>props.loyalty?.settings||props.loyalty||{});
const economics=computed(()=>props.loyalty?.economics||{});
const reversedEventIds=computed(()=>new Set(props.events.map(row=>row.reversesEventId).filter(Boolean)));
const economicsCards=computed(()=>{
  const unit=sourceSettings.value.unitLabel||'points',value=key=>Number(economics.value[key]||0).toLocaleString('en-MY');
  const rows=[{key:'issued',label:'Issued',value:value('issuedPoints'),detail:unit},{key:'redeemed',label:'Redeemed',value:value('redeemedPoints'),detail:unit}];
  if(economics.value.outstandingPoints!=null)rows.push({key:'outstanding',label:'Outstanding',value:value('outstandingPoints'),detail:`plus ${value('reservedPoints')} reserved`});
  else if(economics.value.netPointsMovement!=null)rows.push({key:'movement',label:'Net points movement',value:value('netPointsMovement'),detail:'for this company'});
  rows.push({key:'members',label:'Members',value:value('customerCount'),detail:'with loyalty activity'});
  return rows;
});
const customerId=row=>row.customerId||row.id;
const money=sen=>`${props.currency} ${(Number(sen||0)/100).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const date=value=>value?new Intl.DateTimeFormat('en-MY',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(value)):'—';
const eventPoints=row=>Number(row.points||row.deltaPoints||0);
watch(sourceSettings,value=>{settings.value={expectedVersion:Number(value.version||0),enabled:value.enabled??true,unitLabel:value.unitLabel||'points',earnMode:value.earnMode||'per_order',pointsPerOrder:Number(value.pointsPerOrder||1),spendStep:((Number(value.spendStepSen||100)/100)).toFixed(2),pointsPerSpendStep:Number(value.pointsPerSpendStep||1),minimumSpend:((Number(value.minimumSpendSen||0)/100)).toFixed(2),redemptionThresholdPoints:Number(value.redemptionThresholdPoints||100)};},{immediate:true,deep:true});
function sen(value,label){const source=String(value??'').trim();if(!/^\d+(?:\.\d{1,2})?$/.test(source))throw new Error(`${label} must use at most two decimal places.`);const [whole,fraction='']=source.split('.');return Number(BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0')));}
function save(){try{if(!settings.value.unitLabel.trim())throw new Error('Name the loyalty unit.');const body={expectedVersion:settings.value.expectedVersion,enabled:!!settings.value.enabled,unitLabel:settings.value.unitLabel.trim(),earnMode:settings.value.earnMode,pointsPerOrder:Number(settings.value.pointsPerOrder),spendStepSen:sen(settings.value.spendStep,'Spend step'),pointsPerSpendStep:Number(settings.value.pointsPerSpendStep),minimumSpendSen:sen(settings.value.minimumSpend,'Minimum spend'),redemptionThresholdPoints:Number(settings.value.redemptionThresholdPoints)};for(const key of ['pointsPerOrder','pointsPerSpendStep','redemptionThresholdPoints'])if(!Number.isSafeInteger(body[key])||body[key]<1)throw new Error('Point values must be positive whole numbers.');localError.value='';emit('save-settings',body);}catch(error){localError.value=error.message;}}
function openAction(kind){action.value={kind,customerId:'',points:'',reason:'',idempotencyKey:crypto.randomUUID()};localError.value='';}
function submitAction(){try{const points=Number(action.value.points);if(!Number.isSafeInteger(points)||points===0||action.value.kind==='redeem'&&points<1)throw new Error('Points must be a valid whole number.');if(action.value.reason.trim().length<3)throw new Error('Give a reason of at least 3 characters.');emit('post-event',{kind:action.value.kind,payload:{customerId:action.value.customerId,points,reason:action.value.reason.trim(),idempotencyKey:action.value.idempotencyKey},done:()=>action.value=null});}catch(error){localError.value=error.message;}}
function openReverse(row){reversal.value={row,reason:'',idempotencyKey:crypto.randomUUID()};localError.value='';}
function submitReverse(){if(reversal.value.reason.trim().length<3){localError.value='Give a reason of at least 3 characters.';return;}emit('reverse',{eventId:reversal.value.row.id,payload:{reason:reversal.value.reason.trim(),idempotencyKey:reversal.value.idempotencyKey},done:()=>reversal.value=null});}
</script>

<template>
  <section class="mf-loyalty-platform">
    <div class="ed-section-head"><div><div class="ed-eyebrow">LOYALTY & POINTS</div><h2>Reward repeat behaviour</h2><small>One customer login, a separate balance in each workspace, and an immutable event ledger.</small></div><span class="ed-pill" :class="{ready:sourceSettings.enabled,warning:!sourceSettings.enabled}">{{ sourceSettings.enabled?'Earning active':'Earning paused' }}</span></div>
    <div class="mf-loyalty-economics"><article v-for="card in economicsCards" :key="card.key"><span>{{ card.label }}</span><strong>{{ card.value }}</strong><small>{{ card.detail }}</small></article></div>
    <form class="ed-section mf-loyalty-settings" @submit.prevent="save"><div class="ed-section-head"><div><h3>Workspace earning rule</h3><small>Workspace owners control the shared unit and earning economics.</small></div><label class="mf-switch"><input v-model="settings.enabled" type="checkbox" :disabled="!canConfigure"><span>{{ settings.enabled?'Enabled':'Paused' }}</span></label></div><div class="ed-form-grid"><label class="ed-field"><span>Unit name</span><input v-model="settings.unitLabel" maxlength="30" :disabled="!canConfigure" placeholder="points"></label><label class="ed-field"><span>Earn mode</span><select v-model="settings.earnMode" :disabled="!canConfigure"><option value="per_order">Points per eligible order</option><option value="spend_step">Points for each spend step</option></select></label><label class="ed-field"><span>Points per order</span><input v-model.number="settings.pointsPerOrder" type="number" min="1" step="1" :disabled="!canConfigure||settings.earnMode!=='per_order'"></label><label class="ed-field"><span>Spend step ({{ currency }})</span><input v-model="settings.spendStep" inputmode="decimal" :disabled="!canConfigure||settings.earnMode!=='spend_step'"></label><label class="ed-field"><span>Points per spend step</span><input v-model.number="settings.pointsPerSpendStep" type="number" min="1" step="1" :disabled="!canConfigure||settings.earnMode!=='spend_step'"></label><label class="ed-field"><span>Minimum eligible spend ({{ currency }})</span><input v-model="settings.minimumSpend" inputmode="decimal" :disabled="!canConfigure"></label><label class="ed-field"><span>Default redemption threshold</span><input v-model.number="settings.redemptionThresholdPoints" type="number" min="1" step="1" :disabled="!canConfigure"></label></div><div class="ed-actions"><button v-if="canConfigure" class="ed-btn primary" type="submit" :disabled="busy">{{ busy?'Saving…':'Save loyalty version' }}</button><span v-else class="ed-muted">Managers can adjust and redeem points for customers in this company. A workspace owner changes the shared earning rule.</span></div></form>
    <p v-if="localError||error" class="ed-notice error" role="alert">{{ localError||error }}</p>
    <section class="ed-section"><div class="ed-section-head"><div><h3>Point ledger</h3><small>Manual changes require a reason. Reversal adds a compensating event; history is never deleted.</small></div><div class="ed-actions"><button class="ed-btn small" @click="emit('refresh-events')"><Icon name="clock"/>Refresh</button><button v-if="canAdjust" class="ed-btn small" @click="openAction('adjust')">Adjust</button><button v-if="canAdjust" class="ed-btn primary small" @click="openAction('redeem')">Redeem</button></div></div><div v-for="row in events" :key="row.id" class="ed-row"><span class="ed-avatar"><Icon name="spark"/></span><span style="flex:1"><strong>{{ row.customerName||row.customerId }}</strong><small>{{ row.reason }} · {{ date(row.createdAt) }}</small><small v-if="row.campaignId">Campaign {{ row.campaignId }} · version {{ row.campaignVersion }}</small></span><strong :class="eventPoints(row)>=0?'positive':'negative'">{{ eventPoints(row)>0?'+':'' }}{{ eventPoints(row) }}</strong><span class="ed-pill">Balance {{ row.balanceAfter }}</span><button v-if="canAdjust&&row.kind!=='reverse'&&!reversedEventIds.has(row.id)" class="ed-btn small" @click="openReverse(row)">Reverse</button></div><div v-if="!events.length" class="ed-empty"><Icon name="spark"/><h3>No point activity yet.</h3><p>Eligible paid orders, campaign bonuses and reasoned staff adjustments will appear here.</p></div></section>
    <Modal v-if="action" :title="action.kind==='redeem'?'Redeem customer points':'Adjust customer points'" :busy="busy" @close="action=null"><form id="loyalty-action-form" class="ed-form-grid" @submit.prevent="submitAction"><label class="ed-field wide"><span>Registered customer</span><select v-model="action.customerId" required><option value="" disabled>Select customer</option><option v-for="customer in customers" :key="customerId(customer)" :value="customerId(customer)">{{ customer.displayName||customer.email }} · {{ customer.email }}</option></select></label><label class="ed-field"><span>{{ action.kind==='redeem'?'Points to redeem':'Point change' }}</span><input v-model="action.points" type="number" :min="action.kind==='redeem'?1:undefined" step="1" required><small v-if="action.kind==='adjust'">Use a negative number to remove points.</small></label><label class="ed-field wide"><span>Reason</span><textarea v-model="action.reason" minlength="3" maxlength="500" rows="3" required placeholder="Service recovery, in-store reward…"></textarea></label></form><p v-if="localError||error" class="ed-notice error">{{ localError||error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="action=null">Cancel</button><button class="ed-btn primary" type="submit" form="loyalty-action-form" :disabled="busy">{{ busy?'Recording…':'Record immutable event' }}</button></template></Modal>
    <Modal v-if="reversal" title="Reverse loyalty event" :busy="busy" @close="reversal=null"><div class="ed-notice warning"><Icon name="alert"/><div><strong>History remains intact</strong>MyFin will add an equal and opposite event to the ledger.</div></div><form id="loyalty-reversal-form" @submit.prevent="submitReverse"><label class="ed-field"><span>Reason</span><textarea v-model="reversal.reason" minlength="3" maxlength="500" rows="3" required></textarea></label></form><p v-if="localError||error" class="ed-notice error">{{ localError||error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="reversal=null">Cancel</button><button class="ed-btn danger" type="submit" form="loyalty-reversal-form" :disabled="busy">{{ busy?'Reversing…':'Add reversal event' }}</button></template></Modal>
  </section>
</template>

<style scoped>
.mf-loyalty-platform{display:grid;gap:20px}.mf-loyalty-economics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--ed-line);background:var(--ed-paper)}.mf-loyalty-economics article{padding:18px;border-right:1px solid var(--ed-line);display:grid;gap:6px}.mf-loyalty-economics article:last-child{border:0}.mf-loyalty-economics span,.mf-loyalty-economics small{font-size:9px;color:var(--ed-muted);text-transform:uppercase}.mf-loyalty-economics strong{font:400 27px Georgia,serif}.ed-section{border:1px solid var(--ed-line);padding:22px;background:var(--ed-paper)}.mf-loyalty-settings h3,.ed-section h3{font:400 24px Georgia,serif;margin:0}.mf-switch{display:flex;align-items:center;gap:8px;font-size:11px}.positive{color:#247148}.negative{color:#9b3f2f}.ed-row small{display:block;margin-top:4px}@media(max-width:700px){.mf-loyalty-economics{grid-template-columns:repeat(2,1fr)}.mf-loyalty-economics article:nth-child(2){border-right:0}.mf-loyalty-economics article:nth-child(-n+2){border-bottom:1px solid var(--ed-line)}}
</style>
